import{_ as e,o as t,c as o,al as r}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Установка","description":"Пошаговая инструкция по установке модуля exDoc на OpenCart 3.x — требования, загрузка файлов и запуск установщика.","frontmatter":{"title":"Установка","description":"Пошаговая инструкция по установке модуля exDoc на OpenCart 3.x — требования, загрузка файлов и запуск установщика."},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md"}'),l={name:"getting-started/installation.md"};function i(n,a,s,h,c,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h1><h2 id="требования" tabindex="-1">Требования <a class="header-anchor" href="#требования" aria-label="Permalink to &quot;Требования&quot;">​</a></h2><ul><li>OpenCart 3.x</li><li>PHP 7.x</li><li>MySQL 5.7+ (с поддержкой JSON-колонок)</li></ul><h2 id="шаг-1-загрузка-фаилов" tabindex="-1">Шаг 1. Загрузка файлов <a class="header-anchor" href="#шаг-1-загрузка-фаилов" aria-label="Permalink to &quot;Шаг 1. Загрузка файлов&quot;">​</a></h2><p>Загрузите содержимое папки <code>upload</code> из установочного архива на сервер через FTP в корневую директорию OpenCart.</p><h2 id="шаг-2-запуск-установщика" tabindex="-1">Шаг 2. Запуск установщика <a class="header-anchor" href="#шаг-2-запуск-установщика" aria-label="Permalink to &quot;Шаг 2. Запуск установщика&quot;">​</a></h2><p>Откройте в браузере страницу установщика:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ваш-домен.com/index.php?route=exdoc/install/install</span></span></code></pre></div><blockquote><p><strong>Важно:</strong> Вы должны быть авторизованы в админ-панели OpenCart. Если вы не залогинены — установщик покажет ошибку.</p></blockquote><p>На странице установщика вы увидите форму с тремя переключателями и выбором группы — в таком порядке:</p><h3 id="установить-права" tabindex="-1">Установить права <a class="header-anchor" href="#установить-права" aria-label="Permalink to &quot;Установить права&quot;">​</a></h3><p>Назначает права доступа exDoc <strong>той группе, под которой вы сейчас вошли</strong>. Выдаются права на все разделы модуля: блоки, категории, документы, коллекции, рубрики, шаблоны, поля, настройки, файловый менеджер, SVG-спрайты и остальные.</p><h3 id="установить-базу-данных" tabindex="-1">Установить базу данных <a class="header-anchor" href="#установить-базу-данных" aria-label="Permalink to &quot;Установить базу данных&quot;">​</a></h3><p>Создаёт все необходимые таблицы в базе данных MySQL для работы exDoc. Выполняется SQL-скрипт создания структуры данных.</p><h3 id="удалить-фаилы-установки" tabindex="-1">Удалить файлы установки <a class="header-anchor" href="#удалить-фаилы-установки" aria-label="Permalink to &quot;Удалить файлы установки&quot;">​</a></h3><p>После успешной установки рекомендуется удалить файлы установщика в целях безопасности. При выборе этой опции будут удалены контроллер и модель установки, а вы будете перенаправлены на главную страницу.</p><blockquote><p><strong>Рекомендация:</strong> Оставлять файлы установщика на продакшене небезопасно. Обязательно выберите эту опцию после завершения установки.</p></blockquote><h3 id="группа-суперадминистратора" tabindex="-1">Группа суперадминистратора <a class="header-anchor" href="#группа-суперадминистратора" aria-label="Permalink to &quot;Группа суперадминистратора&quot;">​</a></h3><p>Выберите из выпадающего списка группу пользователей, которая будет иметь полные права в exDoc (суперадмин). По умолчанию предложена ваша текущая группа.</p><h2 id="шаг-3-применение-модификации" tabindex="-1">Шаг 3. Применение модификаций <a class="header-anchor" href="#шаг-3-применение-модификации" aria-label="Permalink to &quot;Шаг 3. Применение модификаций&quot;">​</a></h2><p>После установки перейдите в <strong>Модули → Модификации</strong> и нажмите кнопку <strong>Обновить</strong> для применения OCMOD-модификаций.</p><h2 id="шаг-4-очистка-кэша" tabindex="-1">Шаг 4. Очистка кэша <a class="header-anchor" href="#шаг-4-очистка-кэша" aria-label="Permalink to &quot;Шаг 4. Очистка кэша&quot;">​</a></h2><p>Очистите кэш OpenCart: <strong>Система → Обслуживание → Кэш</strong>. После этого модуль exDoc появится в главном меню админ-панели.</p><h2 id="обновление-до-новои-версии" tabindex="-1">Обновление до новой версии <a class="header-anchor" href="#обновление-до-новои-версии" aria-label="Permalink to &quot;Обновление до новой версии&quot;">​</a></h2><p>Установщик нужен только при первой установке. Для обновления:</p><ol><li>Загрузите файлы новой версии поверх старых.</li><li>Откройте раздел exDoc в админ-панели.</li><li>Обновите модификации и очистите кэш — шаги 3 и 4 выше.</li></ol><p>Структуру базы обновлять руками не нужно: при открытии раздела exDoc сверяет версию схемы в базе с версией модуля и сам применяет недостающие обновления, по одному, по возрастанию версий. Уже применённые пропускаются, так что повторное открытие ничего не ломает.</p><p>Если обновление не удалось, админ-панель продолжит работать, а причина попадёт в <a href="./../log/">лог</a> с уровнем <code>error</code> и источником <code>migration</code>. Версия схемы при этом не сдвинется — после устранения причины следующее открытие раздела повторит попытку с того же места.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li><a href="./interface.html">Обзор интерфейса</a> — как устроена админ-панель exDoc</li><li><a href="./first-steps.html">Первые шаги</a> — создание первого блока и страницы</li></ul>',30)])])}const b=e(l,[["render",i]]);export{u as __pageData,b as default};
